--- data ---
import { cacheLife } from 'next/cache'

export async function getRelatedProducts() {
  'use cache'
  cacheLife('hours')
  return ['Compact Widget', 'Widget Carry Case']
}

--- home ---
import Link from 'next/link'

export default function Home() {
  return (
    <main>
      <h1>Featured product</h1>
      <Link href="/product">View Premium Widget</Link>
    </main>
  )
}

--- product ---
import { getRelatedProducts } from '@/lib/data'

export default async function ProductPage() {
  const relatedProducts = await getRelatedProducts()

  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <ul>
          {relatedProducts.map((product) => (
            <li key={product}>{product}</li>
          ))}
        </ul>
      </section>
    </main>
  )
}

--- layout ---
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Featured product',
  description: 'Shop our featured product',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

